{
  "name": "Claude Code AI Agent with Memory (MCP Integration)",
  "settings": {},
  "nodes": [
    {
      "parameters": {},
      "name": "Manual Trigger",
      "type": "n8n-nodes-base.manualTrigger",
      "typeVersion": 1,
      "position": [240, 400]
    },
    {
      "parameters": {
        "jsCode": "// Generate UUID for session ID\nfunction generateUUID() {\n  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {\n    const r = Math.random() * 16 | 0;\n    const v = c === 'x' ? r : (r & 0x3 | 0x8);\n    return v.toString(16);\n  });\n}\n\nconst sessionId = generateUUID();\nconst userPrompt = $input.item.json.prompt || \"Hello, can you help me with a task?\";\n\nreturn {\n  session_id: sessionId,\n  user_prompt: userPrompt\n};"
      },
      "name": "Generate Session ID",
      "type": "n8n-nodes-base.code",
      "typeVersion": 2,
      "position": [460, 400]
    },
    {
      "parameters": {
        "jsCode": "const prompt = $input.item.json.user_prompt || \"\";\nconst words = prompt.toLowerCase().split(/\\s+/);\n\n// Filter stop words\nconst stopWords = [\"the\", \"is\", \"at\", \"which\", \"on\", \"a\", \"an\", \"and\", \"or\", \"but\", \"can\", \"you\", \"help\", \"me\", \"with\"];\nconst keywords = words\n  .filter(w => w.length > 3 && !stopWords.includes(w))\n  .slice(0, 7)\n  .join(\" \");\n\n// Detect technology categories for tagging\nconst categories = {\n  \"docker\": [\"docker\", \"container\", \"image\", \"dockerfile\"],\n  \"git\": [\"git\", \"commit\", \"branch\", \"repository\", \"github\"],\n  \"python\": [\"python\", \"pip\", \"django\", \"flask\", \"fastapi\"],\n  \"javascript\": [\"javascript\", \"node\", \"npm\", \"typescript\"],\n  \"n8n\": [\"n8n\", \"workflow\", \"automation\"],\n  \"claude\": [\"claude\", \"ai\", \"llm\", \"assistant\"],\n  \"database\": [\"database\", \"sql\", \"postgres\", \"mysql\", \"mongodb\"],\n  \"cloud\": [\"aws\", \"azure\", \"gcp\", \"cloudflare\"]\n};\n\nlet detectedTags = [\"n8n\", \"claude-code\"];\nfor (const [tag, kwList] of Object.entries(categories)) {\n  if (kwList.some(kw => prompt.toLowerCase().includes(kw))) {\n    detectedTags.push(tag);\n  }\n}\n\nreturn {\n  session_id: $input.item.json.session_id,\n  user_prompt: prompt,\n  keywords: keywords || prompt,\n  detected_tags: detectedTags\n};"
      },
      "name": "Extract Keywords & Detect Topics",
      "type": "n8n-nodes-base.code",
      "typeVersion": 2,
      "position": [680, 400]
    },
    {
      "parameters": {
        "method": "POST",
        "url": "http://localhost:8000/api/search",
        "sendHeaders": true,
        "headerParameters": {
          "parameters": [
            {
              "name": "Content-Type",
              "value": "application/json"
            }
          ]
        },
        "sendBody": true,
        "bodyParameters": {
          "parameters": [
            {
              "name": "query",
              "value": "={{ $json.keywords }}"
            },
            {
              "name": "n_results",
              "value": 5
            },
            {
              "name": "quality_boost",
              "value": true
            },
            {
              "name": "quality_weight",
              "value": 0.3
            }
          ]
        },
        "options": {
          "timeout": 5000
        }
      },
      "name": "Memory Service - Semantic Search",
      "type": "n8n-nodes-base.httpRequest",
      "typeVersion": 4,
      "position": [900, 400],
      "continueOnFail": true
    },
    {
      "parameters": {
        "jsCode": "const searchResponse = $input.item.json;\nconst results = (searchResponse && searchResponse.results) || [];\n\nif (results.length === 0) {\n  return {\n    session_id: $input.item.json.session_id,\n    user_prompt: $input.item.json.user_prompt,\n    context: \"\",\n    memory_count: 0,\n    detected_tags: $input.item.json.detected_tags\n  };\n}\n\n// Format memories with relevance scores\nconst contextText = results\n  .map((r, i) => {\n    const content = r.memory.content;\n    const score = r.similarity_score ? r.similarity_score.toFixed(3) : 'N/A';\n    const tags = r.memory.tags.join(\", \");\n    return `[Memory ${i+1}] (Relevance: ${score}, Tags: ${tags})\\n${content}`;\n  })\n  .join(\"\\n\\n---\\n\\n\");\n\nreturn {\n  session_id: $input.item.json.session_id,\n  user_prompt: $input.item.json.user_prompt,\n  context: contextText,\n  memory_count: results.length,\n  detected_tags: $input.item.json.detected_tags\n};"
      },
      "name": "Format Retrieved Context",
      "type": "n8n-nodes-base.code",
      "typeVersion": 2,
      "position": [1120, 400]
    },
    {
      "parameters": {
        "jsCode": "const prompt = $input.item.json.user_prompt;\nconst context = $input.item.json.context;\nconst memoryCount = $input.item.json.memory_count;\n\nlet enhanced;\nif (context && memoryCount > 0) {\n  enhanced = `[CONTEXT FROM PREVIOUS SESSIONS - ${memoryCount} relevant memories found]\\n\\n${context}\\n\\n---\\n\\n[CURRENT REQUEST]\\n${prompt}\\n\\n[INSTRUCTIONS]\\nPlease assist with the current request above. Use the context from previous sessions if relevant, but focus primarily on the current request. If the context helps, mention how it informed your response.`;\n} else {\n  enhanced = prompt;\n}\n\nreturn {\n  session_id: $input.item.json.session_id,\n  prompt: enhanced,\n  user_prompt: prompt,\n  detected_tags: $input.item.json.detected_tags\n};"
      },
      "name": "Build Enhanced Prompt",
      "type": "n8n-nodes-base.code",
      "typeVersion": 2,
      "position": [1340, 400]
    },
    {
      "parameters": {
        "command": "=claude -p \"{{ $json.prompt }}\" --session-id {{ $json.session_id }}",
        "cwd": "~"
      },
      "name": "SSH - Initial Claude Command",
      "type": "n8n-nodes-base.ssh",
      "typeVersion": 1,
      "position": [1560, 400],
      "credentials": {
        "sshPrivateKey": {
          "id": "1",
          "name": "SSH Claude Server"
        }
      }
    },
    {
      "parameters": {
        "jsCode": "const response = $input.item.json.stdout || \"\";\nconst userPrompt = $input.item.json.user_prompt;\n\n// Extract sentences with importance indicators\nconst sentences = response.split(/[.!?]+/).filter(s => s.trim().length > 0);\n\n// Heuristic: sentences containing these patterns are likely important\nconst importancePatterns = [\n  /important|crucial|key|note|remember|essential/i,\n  /solution|fix|resolved|solved/i,\n  /configured|setup|installed|created/i,\n  /error|issue|problem.*fixed/i,\n  /decided|concluded|determined/i,\n  /found that|discovered|learned/i\n];\n\nconst importantSentences = sentences.filter(s => \n  importancePatterns.some(pattern => pattern.test(s))\n);\n\n// Also extract code blocks if present\nconst codeBlocks = response.match(/```[\\s\\S]*?```/g) || [];\n\nlet extractableFacts = importantSentences.slice(0, 5).join(\". \");\nif (codeBlocks.length > 0) {\n  extractableFacts += \"\\n\\n\" + codeBlocks.slice(0, 2).join(\"\\n\\n\");\n}\n\nconst hasContent = extractableFacts.length > 20;\n\nreturn {\n  session_id: $input.item.json.session_id,\n  full_response: response,\n  extractable_facts: hasContent ? extractableFacts : \"Session interaction completed\",\n  user_prompt: userPrompt,\n  detected_tags: $input.item.json.detected_tags,\n  has_extractable_content: hasContent\n};"
      },
      "name": "Parse & Extract Important Facts",
      "type": "n8n-nodes-base.code",
      "typeVersion": 2,
      "position": [1780, 400]
    },
    {
      "parameters": {
        "method": "POST",
        "url": "http://localhost:8000/api/memories",
        "sendHeaders": true,
        "headerParameters": {
          "parameters": [
            {
